import { useState } from "react";

export function Checklist({ items }) {
  const [done, setDone] = useState({});
  return (
    <ul>
      {items.map((item) => (
        <li key={item}>
          <label>
            <input
              type="checkbox"
              checked={!!done[item]}
              onChange={() => setDone((d) => ({ ...d, [item]: !d[item] }))}
            />
            {item}
          </label>
        </li>
      ))}
    </ul>
  );
}
